$path = "index.html"
$b64 = ""
$bytes = [Convert]::FromBase64String($b64)
[System.IO.File]::WriteAllBytes((Join-Path (Get-Location) $path), $bytes)
$check = [System.IO.File]::ReadAllText((Join-Path (Get-Location) $path))
if ($check.Contains("15 Days Free Trial")) { Write-Output "15-day trial text: OK" } else { Write-Output "15-day trial text: MISSING" }
if ($check.Contains("1 Month Free Trial")) { Write-Output "Old 1-month text still present: PROBLEM" } else { Write-Output "Old 1-month text: gone, correct" }
if ($check.Contains("logo.png")) { Write-Output "logo.png reference: OK" } else { Write-Output "logo.png reference: MISSING" }
Write-Output "Now run: firebase deploy --only hosting"
